using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static DistributedApplication? s_app;
    private static IChatClient? s_chatClient;
    private static ChatConfiguration? s_chatConfiguration;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        var appHost = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        s_app = await appHost.BuildAsync();
        await s_app.StartAsync();

        s_chatClient = s_app.Services.GetRequiredService<IChatClient>();
        s_chatConfiguration = new ChatConfiguration(s_chatClient);
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (s_app is not null)
        {
            await s_app.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_Response_Is_Coherent()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant. Keep responses concise."),
            new(ChatRole.User, "What is dependency injection?")
        };

        var response = await s_chatClient!.GetResponseAsync(messages);

        var evaluator = new CoherenceEvaluator();
        var result = await evaluator.EvaluateAsync(messages, response, s_chatConfiguration!);

        var coherence = result.Get<NumericMetric>(CoherenceEvaluator.CoherenceMetricName);
        Assert.IsFalse(coherence.Interpretation!.Failed, $"Coherence evaluation failed. Score: {coherence.Value}");
        Assert.IsTrue(
            coherence.Interpretation.Rating is EvaluationRating.Good or EvaluationRating.Exceptional,
            $"Coherence rating was {coherence.Interpretation.Rating} (score: {coherence.Value})");
    }

    [TestMethod]
    public async Task Chat_Response_Is_Relevant()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant. Keep responses concise."),
            new(ChatRole.User, "Explain the difference between a list and a dictionary in C#.")
        };

        var response = await s_chatClient!.GetResponseAsync(messages);

        var evaluator = new RelevanceEvaluator();
        var result = await evaluator.EvaluateAsync(messages, response, s_chatConfiguration!);

        var relevance = result.Get<NumericMetric>(RelevanceEvaluator.RelevanceMetricName);
        Assert.IsFalse(relevance.Interpretation!.Failed, $"Relevance evaluation failed. Score: {relevance.Value}");
        Assert.IsTrue(
            relevance.Interpretation.Rating is EvaluationRating.Good or EvaluationRating.Exceptional,
            $"Relevance rating was {relevance.Interpretation.Rating} (score: {relevance.Value})");
    }

    [TestMethod]
    public async Task Chat_Response_Is_Fluent()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant. Keep responses concise."),
            new(ChatRole.User, "How do you configure middleware in ASP.NET Core?")
        };

        var response = await s_chatClient!.GetResponseAsync(messages);

        var evaluator = new FluencyEvaluator();
        var result = await evaluator.EvaluateAsync(messages, response, s_chatConfiguration!);

        var fluency = result.Get<NumericMetric>(FluencyEvaluator.FluencyMetricName);
        Assert.IsFalse(fluency.Interpretation!.Failed, $"Fluency evaluation failed. Score: {fluency.Value}");
        Assert.IsTrue(
            fluency.Interpretation.Rating is EvaluationRating.Good or EvaluationRating.Exceptional,
            $"Fluency rating was {fluency.Interpretation.Rating} (score: {fluency.Value})");
    }

    [TestMethod]
    public async Task Chat_Response_Completeness()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant. Keep responses concise."),
            new(ChatRole.User, "List three benefits of using async/await in C#.")
        };

        var response = await s_chatClient!.GetResponseAsync(messages);

        var evaluator = new CompletenessEvaluator();
        var result = await evaluator.EvaluateAsync(messages, response, s_chatConfiguration!);

        var completeness = result.Get<NumericMetric>(CompletenessEvaluator.CompletenessMetricName);
        Assert.IsFalse(completeness.Interpretation!.Failed, $"Completeness evaluation failed. Score: {completeness.Value}");
        Assert.IsTrue(
            completeness.Interpretation.Rating is EvaluationRating.Good or EvaluationRating.Exceptional,
            $"Completeness rating was {completeness.Interpretation.Rating} (score: {completeness.Value})");
    }
}

